mapper.select:
SELECT id, channel, scene_code AS templateCode, template_name, description, subject, im_message_type AS imMessageType, priority, status, created_at, updated_at, created_by, updated_by FROM message_template
channel = #{query.channel}
AND scene_code LIKE CONCAT('%', #{query.templateCode}, '%')
AND template_name LIKE CONCAT('%', #{query.templateName}, '%')
AND subject LIKE CONCAT('%', #{query.subject}, '%')
AND im_message_type = #{query.imMessageType}
AND status = #{query.status}
ORDER BY created_at DESC
